import{r as a,o as r,a as c,b as t,d as n,w as i,F as d,c as s,e}from"./app.279f3668.js";import{_ as l}from"./plugin-vue_export-helper.21dcd24c.js";const h={},p=s('<h1 id="creating-ims-projects" tabindex="-1"><a class="header-anchor" href="#creating-ims-projects" aria-hidden="true">#</a> Creating IMS Projects</h1><h2 id="overview" tabindex="-1"><a class="header-anchor" href="#overview" aria-hidden="true">#</a> Overview</h2><p>IMS Explorer for VS Code allows you to create IMS projects to execute SQL queries against IMS databases, run IMS type-1 and type-2 commands, and edit DBD fields and database definitions. Use the following steps to create IMS projects in the <strong>IMS Projects</strong> view and to work with SQL, command, and DBD files within those projects.</p><h2 id="step-1-open-the-ims-projects-view" tabindex="-1"><a class="header-anchor" href="#step-1-open-the-ims-projects-view" aria-hidden="true">#</a> Step 1: Open the IMS Projects View</h2><ol><li>In Visual Studio Code, open the <strong>IMS Projects</strong> view from the Activity Bar.</li></ol><blockquote><p>This view allows you to create, edit, and organize SQL, command, and DBD project files used with IMS databases.</p></blockquote><h2 id="step-2-create-a-new-ims-project" tabindex="-1"><a class="header-anchor" href="#step-2-create-a-new-ims-project" aria-hidden="true">#</a> Step 2: Create a New IMS Project</h2><ol><li>In the <strong>IMS Projects</strong> view, click <strong>Create Project</strong>.</li><li>Provide a project name when prompted.</li></ol><blockquote><p>The project appears in the view. You can create multiple projects to manage SQL files.</p></blockquote><h2 id="step-3-create-sql-files-in-the-project" tabindex="-1"><a class="header-anchor" href="#step-3-create-sql-files-in-the-project" aria-hidden="true">#</a> Step 3: Create SQL Files in the Project</h2><ol><li>Right-click the new project and select <strong>New SQL File</strong>.</li><li>Enter a name for your SQL file.</li></ol><blockquote><p>The file opens in the editor, where you can structure SQL queries.</p></blockquote><h2 id="step-4-import-dbds-and-psbs-from-catalog" tabindex="-1"><a class="header-anchor" href="#step-4-import-dbds-and-psbs-from-catalog" aria-hidden="true">#</a> Step 4: Import DBDs and PSBs from Catalog</h2><ol><li>Right-click the project and select <strong>Import from Catalog</strong>. Or alternatively, select the <strong>Import from catalog</strong> button next to the project name.</li><li>Select an IMS database connection to import from.</li><li>Filter and select DBDs and PSBs to import.</li><li>Optionally, choose to import referenced DBDs.</li><li>Edit any project files as needed: <ul><li>Open SQL files to write or edit SQL statements.</li><li>Open DDL or source code files to edit database definitions.</li></ul></li></ol><blockquote><p>Imported DBDs and PSBs can be viewed and edited within the project. SQL syntax highlighting and validation are provided by the IMS Explorer extension. <strong>Note:</strong> Source and DDL views display a snapshot of the current state that can be edited within the editor. If you edit these files, the views will not automatically refresh another.</p></blockquote><h2 id="step-5-execute-sql-against-an-ims-connection" tabindex="-1"><a class="header-anchor" href="#step-5-execute-sql-against-an-ims-connection" aria-hidden="true">#</a> Step 5: Execute SQL Against an IMS Connection</h2><ol><li>Ensure you have created an IMS database connection in the <strong>IMS Connections</strong> view.</li><li>Select the IMS database connection you wish to execute the SQL query on in the status bar or by using the <strong>IMS Connections</strong> view.</li><li>Run SQL directly from the SQL editor using the Run button at the top-right of the editor window.</li><li>Query results appear in a results view where you can sort, filter, and download rows as CSV.</li></ol>',17),u=e("Executing SQL requires an IMS database connection. To create a connection, see "),m=e("Creating IMS Connections"),g=e("."),S=s('<h2 id="step-6-add-ims-ddl-files-optional" tabindex="-1"><a class="header-anchor" href="#step-6-add-ims-ddl-files-optional" aria-hidden="true">#</a> Step 6: Add IMS DDL Files (optional)</h2><p>IMS projects support editing and executing IMS DDL statements to create or modify DBD and PSB definitions.</p><ol><li>In the <strong>IMS Projects</strong> view, right-click your project and select <strong>New SQL File</strong>.</li><li>Enter a name for the file (for example, <code>create-dbd</code>).</li><li>Write the IMS DDL statements in the file. The DBD definition (all <code>CREATE DATABASE</code>, <code>CREATE TABLESPACE</code>, and <code>CREATE TABLE</code> statements) must be submitted as one unit ending with <code>COMMIT DDL</code>. The PSB definition must be submitted in a separate, subsequent run after the DBD has been committed and imported.</li><li>At the top of the file, select the <strong>IMS Connection</strong> CodeLens to associate an IMS database connection.</li><li>Click the <strong>Execute</strong> button to run the DDL against the selected connection.</li><li>After a successful <code>COMMIT DDL</code>, issue an <code>IMPORT DEFN SOURCE(CATALOG)</code> command to activate the changes in IMS.</li></ol>',3),f=t("strong",null,"Note:",-1),_=e(" The PSB program view must use "),I=t("code",null,"DFSCP001",-1),b=e(" as the user PSB. For full details and code examples, see "),M=e("Editing and Executing IMS DDL"),w=e("."),D=t("h2",{id:"step-7-add-ims-command-files-optional",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#step-7-add-ims-command-files-optional","aria-hidden":"true"},"#"),e(" Step 7: Add IMS Command Files (optional)")],-1),C=t("p",null,[e("IMS projects also support IMS type-1 and type-2 command execution through a "),t("strong",null,"COMMAND"),e(" folder.")],-1),x=t("strong",null,"Prerequisite:",-1),j=e(" An IMS command connection must be configured in the "),L=t("strong",null,"IMS Connections",-1),y=e(" view before you can run commands. See "),v=e("Creating IMS Connections"),E=e("."),k=s("<ol><li>In the <strong>IMS Projects</strong> view, right-click the <strong>COMMAND</strong> folder inside your project.</li><li>Select <strong>Add IMS Command File</strong> from the context menu.</li><li>Enter a name for the file (for example, <code>db-status</code>).</li><li>The file opens in the editor, ready for you to write commands.</li></ol><p>You can create multiple command files to organize commands by task\u2014for example, separate files for database commands, transaction commands, and program commands. Command files are plain-text files stored in your project folder and can be kept in source control alongside your SQL files.</p>",2),B=e("For full details on writing and running commands, see "),P=e("Executing IMS Commands"),q=e(".");function A(Q,T){const o=a("RouterLink");return r(),c(d,null,[p,t("blockquote",null,[t("p",null,[u,n(o,{to:"/Docs/Creating-IMS-Connections.html"},{default:i(()=>[m]),_:1}),g])]),S,t("blockquote",null,[t("p",null,[f,_,I,b,n(o,{to:"/Docs/Editing-and-Executing-IMS-DDL.html"},{default:i(()=>[M]),_:1}),w])]),D,C,t("blockquote",null,[t("p",null,[x,j,L,y,n(o,{to:"/Docs/Creating-IMS-Connections.html#creating-an-ims-command-connection"},{default:i(()=>[v]),_:1}),E])]),k,t("p",null,[B,n(o,{to:"/Docs/Executing-IMS-Commands.html"},{default:i(()=>[P]),_:1}),q])],64)}var N=l(h,[["render",A]]);export{N as default};
